const GEAR_BY_ID = Object.fromEntries(GEAR_MANIFEST.map((g) => [g.id, g]));

function gearStyle(id, scale) {
  const g = GEAR_BY_ID[id];
  if (!g) return { display: "none" };
  return {
    width: GEAR_FRAME * scale, height: GEAR_FRAME * scale,
    backgroundImage: `url(${GEAR_ATLAS})`,
    backgroundPosition: `-${g.col * GEAR_FRAME * scale}px -${g.row * GEAR_FRAME * scale}px`,
    backgroundSize: `${GEAR_COLS * GEAR_FRAME * scale}px ${GEAR_ROWS * GEAR_FRAME * scale}px`,
    imageRendering: "pixelated",
  };
}

